  transition: transform .12s ease, background .15s, color .15s, border-color .15s;
  white-space: nowrap;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn-primary:hover { background: var(--accent-strong); }
.btn-ghost {
  background: transparent;
  color: var(--text);
  border-color: var(--line-strong);
}
.btn-ghost:hover { background: var(--bg-elev); border-color: var(--text-soft); }

.link-arrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--accent);
  text-decoration: none;
  font-weight: 600;
  font-size: .92rem;
  border-bottom: 1px solid transparent;
  padding-bottom: 2px;
  transition: border-color .15s, color .15s;
}
.link-arrow:hover { color: var(--accent-strong); border-color: currentColor; }

.section-link {
  color: var(--text-muted);
  text-decoration: none;
  font-weight: 500;
  font-size: .92rem;
  display: inline-flex;
  gap: 6px;
  align-items: center;
}
.section-link:hover { color: var(--text); }

/* Section heads */
section { padding: 72px 0; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}
.section-head h2 { font-size: clamp(1.7rem, 3vw, 2.2rem); }

/* Hero */
.hero { padding: 56px 0 40px; }
.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, .95fr);
  gap: 56px;
  align-items: center;
}
.hero h1 {
  font-size: clamp(2.4rem, 6vw, 4.4rem);
  margin: 8px 0 18px;
  letter-spacing: -0.02em;
}
.lede {
  color: var(--text-muted);
  font-size: 1.1rem;
  max-width: 50ch;
  margin: 0 0 28px;
}
.hero-cta {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 40px;
}
.hero-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 18px;
  margin: 0;
  padding-top: 24px;
  border-top: 1px solid var(--line);
  max-width: 520px;
}
.hero-stats > div { min-width: 0; }
.hero-stats dt {
  color: var(--text-soft);
  font-size: .75rem;
  letter-spacing: .14em;
  text-transform: uppercase;
  margin-bottom: 4px;
}
.hero-stats dd {
  margin: 0;
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 1.05rem;
}

/* Hero art (CSS-only illustrations) */
.hero-art {
  position: relative;
  aspect-ratio: 5 / 4;
  min-height: 420px;
}
.hero-card {
  position: absolute;
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
  background: var(--bg-elev);
}
.hero-card-a {
  inset: 0 30% 25% 0;
  background:
    radial-gradient(120% 80% at 30% 20%, rgba(217,179,130,.18), transparent 60%),
    linear-gradient(160deg, #1d2129, #14171e);
}
.hero-card-b {
  inset: 18% 0 35% 45%;
  background:
    radial-gradient(80% 80% at 80% 80%, rgba(120,150,210,.15), transparent 60%),
    linear-gradient(200deg, #1a1d26, #0f1217);
}
.hero-card-c {
  inset: 60% 22% 0 18%;
  background:
    linear-gradient(170deg, #181b23, #0e1116);
}
.hero-tag {
  position: absolute;
  top: 14px; left: 14px;
  font-size: .7rem;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--text-muted);
  background: rgba(0,0,0,.4);
  border: 1px solid var(--line);
  padding: 5px 10px;
  border-radius: 999px;
