}
.hero-illus { position: absolute; inset: 0; }
.illus-lamp::before {
  content: "";
  position: absolute;
  left: 50%; top: 18%;
  width: 60%; height: 60%;
  transform: translateX(-50%);
  background:
    radial-gradient(circle at 50% 30%, rgba(217,179,130,.55), rgba(217,179,130,0) 55%),
