  border-color: var(--line-strong);
  background: var(--bg-elev-2);
}
.cat-emoji { font-size: 1.6rem; line-height: 1; }

/* Filter chips */
.filter-bar {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.chip {
  padding: 8px 14px;
  background: transparent;
  color: var(--text-muted);
