  transition: color .15s, background .15s, border-color .15s;
  font-family: inherit;
}
.chip:hover { color: var(--text); border-color: var(--line-strong); }
.chip.is-active {
  background: var(--text);
  color: var(--bg);
  border-color: var(--text);
}

/* Product grid */
.product-grid {
  list-style: none; padding: 0; margin: 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(0,1fr));
  gap: 22px;
}
.product {
  display: flex;
  flex-direction: column;
  background: var(--bg-elev);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform .15s, border-color .15s;
}
.product:hover { transform: translateY(-3px); border-color: var(--line-strong); }
.product-media {
  position: relative;
  aspect-ratio: 4 / 5;
  overflow: hidden;
}
.product-art {
  position: absolute; inset: 0;
}
.product-tag {
  position: absolute;
  top: 12px; left: 12px;
  font-size: .68rem;
  letter-spacing: .14em;
  text-transform: uppercase;
  font-weight: 700;
  padding: 5px 9px;
  border-radius: 999px;
  background: rgba(11,12,16,.7);
  color: var(--text);
  border: 1px solid var(--line);
}
.product-tag.new { color: var(--accent); border-color: rgba(217,179,130,.4); }
.product-tag.sale { color: #ffb3b3; border-color: rgba(255,140,140,.4); }

.product-fav {
  position: absolute;
  top: 10px; right: 10px;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(11,12,16,.6);
