}
.add-btn:hover { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }

/* Product art variants */
.art-1 { background:
  radial-gradient(80% 60% at 50% 35%, rgba(217,179,130,.35), transparent 60%),
  linear-gradient(160deg, #20242e, #11141a); }
.art-1::after {
  content: ""; position: absolute;
  left: 50%; top: 30%; width: 38%; height: 38%;
  transform: translateX(-50%);
  border-radius: 50%;
