  box-shadow: 0 30px 60px -20px rgba(0,0,0,.7);
}
.art-2 { background:
  linear-gradient(170deg, #1a1f29, #0d1015);
}
.art-2::before, .art-2::after {
  content: ""; position: absolute;
  background: linear-gradient(180deg, #2a2f3a, #14171e);
  border: 1px solid #353b48;
  border-radius: 8px;
}
.art-2::before { left: 22%; bottom: 18%; width: 24%; height: 55%; }
.art-2::after  { left: 52%; bottom: 18%; width: 28%; height: 70%; }

.art-3 { background:
  radial-gradient(70% 50% at 50% 60%, rgba(140,170,220,.18), transparent 60%),
