  linear-gradient(160deg, #2a2218, #110d08); }
.deal-illus-a::after {
  content: ""; position: absolute;
  left: 25%; top: 25%; right: 25%; bottom: 25%;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #e9c79a, #5a431f 70%);
  box-shadow: 0 30px 60px -20px rgba(0,0,0,.7);
}
.deal-illus-b { background:
  linear-gradient(170deg, #1d2429, #0d1216); }
.deal-illus-b::after {
  content: ""; position: absolute;
  inset: 30% 28%;
  background: linear-gradient(180deg, #b8c9d4, #54636e);
  border-radius: 14px 14px 30px 30px;
