@@ -1,0 +1,1123 @@
+:root {
+  --bg: #0b0c10;
+  --bg-elev: #14161c;
+  --bg-elev-2: #1b1e26;
+  --surface: #1f232c;
+  --line: #2a2f3a;
+  --line-strong: #3a4150;
+  --text: #ecedf1;
+  --text-muted: #a4a9b6;
+  --text-soft: #757b88;
+  --accent: #d9b382;
+  --accent-strong: #e9c79a;
+  --accent-ink: #1a1408;
+  --danger: #ff8b8b;
+  --success: #8ce0a8;
+  --focus: #ffd28a;
+  --radius: 14px;
+  --radius-lg: 22px;
+  --shadow: 0 1px 0 rgba(255,255,255,.04) inset, 0 20px 40px -20px rgba(0,0,0,.6);
+  --container: 1200px;
+  --font-sans: "Inter", system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
+  --font-display: "Fraunces", Georgia, "Times New Roman", serif;
+}
+
+* { box-sizing: border-box; }
+
+html { color-scheme: dark; }
+
+body {
+  margin: 0;
+  font-family: var(--font-sans);
+  color: var(--text);
+  background:
+    radial-gradient(1200px 600px at 80% -10%, rgba(217,179,130,.08), transparent 60%),
+    radial-gradient(900px 500px at -10% 20%, rgba(110,140,200,.06), transparent 60%),
+    var(--bg);
+  -webkit-font-smoothing: antialiased;
+  text-rendering: optimizeLegibility;
+  line-height: 1.55;
+  min-width: 320px;
+}
+
+img, svg { display: block; max-width: 100%; }
+
+a { color: inherit; }
+
+:focus-visible {
+  outline: 2px solid var(--focus);
+  outline-offset: 3px;
+  border-radius: 6px;
+}
+
+.container {
+  width: 100%;
+  max-width: var(--container);
+  margin: 0 auto;
+  padding: 0 24px;
+}
+
+.visually-hidden {
+  position: absolute !important;
+  width: 1px; height: 1px;
+  padding: 0; margin: -1px;
+  overflow: hidden; clip: rect(0,0,0,0);
+  white-space: nowrap; border: 0;
+}
+
+/* Skip link */
+.skip-link {
+  position: absolute;
+  left: 12px; top: -40px;
+  background: var(--accent);
+  color: var(--accent-ink);
+  padding: 8px 14px;
+  border-radius: 8px;
+  font-weight: 600;
+  z-index: 100;
+  text-decoration: none;
+  transition: top .15s ease;
+}
+.skip-link:focus { top: 12px; }
+
+/* Announcement bar */
+.announcement {
+  background: linear-gradient(90deg, #14161c, #1a1d26, #14161c);
+  border-bottom: 1px solid var(--line);
+  text-align: center;
+  font-size: .85rem;
+  color: var(--text-muted);
+}
+.announcement p { margin: 0; padding: 10px 16px; }
+
+/* Header */
+.site-header {
+  position: sticky;
+  top: 0;
+  z-index: 50;
+  background: rgba(11,12,16,.78);
+  backdrop-filter: saturate(140%) blur(14px);
+  -webkit-backdrop-filter: saturate(140%) blur(14px);
+  border-bottom: 1px solid var(--line);
+}
+.header-inner {
+  display: flex;
+  align-items: center;
+  gap: 24px;
+  padding: 14px 24px;
+  min-height: 64px;
+}
+.brand {
+  display: inline-flex;
+  align-items: center;
+  gap: 10px;
+  text-decoration: none;
+  color: var(--text);
+  font-family: var(--font-display);
+  font-weight: 700;
+  letter-spacing: .12em;
+}
+.brand-word { font-size: 1.05rem; }
+.brand-mark { color: var(--accent); }
+
+.primary-nav { margin-left: 16px; }
+.primary-nav ul {
+  list-style: none;
+  display: flex;
+  gap: 4px;
+  margin: 0; padding: 0;
+}
+.primary-nav a {
+  display: inline-block;
+  padding: 8px 14px;
+  border-radius: 8px;
+  text-decoration: none;
+  color: var(--text-muted);
+  font-size: .92rem;
+  font-weight: 500;
+  transition: color .15s ease, background .15s ease;
+}
+.primary-nav a:hover { color: var(--text); background: var(--bg-elev); }
+
+.header-actions {
+  display: flex;
+  align-items: center;
+  gap: 4px;
+  margin-left: auto;
+}
+.icon-btn {
+  position: relative;
+  display: inline-grid;
+  place-items: center;
+  width: 40px; height: 40px;
+  background: transparent;
+  color: var(--text-muted);
+  border: 1px solid transparent;
+  border-radius: 10px;
+  cursor: pointer;
+  transition: color .15s, background .15s, border-color .15s;
+}
+.icon-btn:hover { color: var(--text); background: var(--bg-elev); border-color: var(--line); }
+.cart-count {
+  position: absolute;
+  top: 4px; right: 4px;
+  min-width: 18px; height: 18px;
+  padding: 0 5px;
+  border-radius: 999px;
+  background: var(--accent);
+  color: var(--accent-ink);
+  font-size: .7rem;
+  font-weight: 700;
+  display: grid;
+  place-items: center;
+  line-height: 1;
+}
+
+/* Typography helpers */
+.eyebrow {
+  margin: 0 0 12px;
+  font-size: .78rem;
+  letter-spacing: .18em;
+  text-transform: uppercase;
+  color: var(--accent);
+  font-weight: 600;
+}
+h1, h2, h3 {
+  font-family: var(--font-display);
+  font-weight: 600;
+  line-height: 1.1;
+  margin: 0;
+  letter-spacing: -0.01em;
+}
+h1 em { font-style: italic; color: var(--accent); }
+
+/* Buttons */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 8px;
+  padding: 13px 22px;
+  border-radius: 999px;
+  border: 1px solid transparent;
+  font-family: var(--font-sans);
+  font-size: .95rem;
+  font-weight: 600;
+  text-decoration: none;
+  cursor: pointer;
+  transition: transform .12s ease, background .15s, color .15s, border-color .15s;
+  white-space: nowrap;
+}
+.btn:active { transform: translateY(1px); }
+.btn-primary {
+  background: var(--accent);
+  color: var(--accent-ink);
+}
+.btn-primary:hover { background: var(--accent-strong); }
+.btn-ghost {
+  background: transparent;
+  color: var(--text);
+  border-color: var(--line-strong);
+}
+.btn-ghost:hover { background: var(--bg-elev); border-color: var(--text-soft); }
+
+.link-arrow {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  color: var(--accent);
+  text-decoration: none;
+  font-weight: 600;
+  font-size: .92rem;
+  border-bottom: 1px solid transparent;
+  padding-bottom: 2px;
+  transition: border-color .15s, color .15s;
+}
+.link-arrow:hover { color: var(--accent-strong); border-color: currentColor; }
+
+.section-link {
+  color: var(--text-muted);
+  text-decoration: none;
+  font-weight: 500;
+  font-size: .92rem;
+  display: inline-flex;
+  gap: 6px;
+  align-items: center;
+}
+.section-link:hover { color: var(--text); }
+
+/* Section heads */
+section { padding: 72px 0; }
+.section-head {
+  display: flex;
+  align-items: end;
+  justify-content: space-between;
+  gap: 24px;
+  margin-bottom: 32px;
+  flex-wrap: wrap;
+}
+.section-head h2 { font-size: clamp(1.7rem, 3vw, 2.2rem); }
+
+/* Hero */
+.hero { padding: 56px 0 40px; }
+.hero-grid {
+  display: grid;
+  grid-template-columns: minmax(0, 1.05fr) minmax(0, .95fr);
+  gap: 56px;
+  align-items: center;
+}
+.hero h1 {
+  font-size: clamp(2.4rem, 6vw, 4.4rem);
+  margin: 8px 0 18px;
+  letter-spacing: -0.02em;
+}
+.lede {
+  color: var(--text-muted);
+  font-size: 1.1rem;
+  max-width: 50ch;
+  margin: 0 0 28px;
+}
+.hero-cta {
+  display: flex;
+  gap: 12px;
+  flex-wrap: wrap;
+  margin-bottom: 40px;
+}
+.hero-stats {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0,1fr));
+  gap: 18px;
+  margin: 0;
+  padding-top: 24px;
+  border-top: 1px solid var(--line);
+  max-width: 520px;
+}
+.hero-stats > div { min-width: 0; }
+.hero-stats dt {
+  color: var(--text-soft);
+  font-size: .75rem;
+  letter-spacing: .14em;
+  text-transform: uppercase;
+  margin-bottom: 4px;
+}
+.hero-stats dd {
+  margin: 0;
+  font-family: var(--font-display);
+  font-weight: 600;
+  font-size: 1.05rem;
+}
+
+/* Hero art (CSS-only illustrations) */
+.hero-art {
+  position: relative;
+  aspect-ratio: 5 / 4;
+  min-height: 420px;
+}
+.hero-card {
+  position: absolute;
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  border: 1px solid var(--line);
+  box-shadow: var(--shadow);
+  background: var(--bg-elev);
+}
+.hero-card-a {
+  inset: 0 30% 25% 0;
+  background:
+    radial-gradient(120% 80% at 30% 20%, rgba(217,179,130,.18), transparent 60%),
+    linear-gradient(160deg, #1d2129, #14171e);
+}
+.hero-card-b {
+  inset: 18% 0 35% 45%;
+  background:
+    radial-gradient(80% 80% at 80% 80%, rgba(120,150,210,.15), transparent 60%),
+    linear-gradient(200deg, #1a1d26, #0f1217);
+}
+.hero-card-c {
+  inset: 60% 22% 0 18%;
+  background:
+    linear-gradient(170deg, #181b23, #0e1116);
+}
+.hero-tag {
+  position: absolute;
+  top: 14px; left: 14px;
+  font-size: .7rem;
+  letter-spacing: .16em;
+  text-transform: uppercase;
+  color: var(--text-muted);
+  background: rgba(0,0,0,.4);
+  border: 1px solid var(--line);
+  padding: 5px 10px;
+  border-radius: 999px;
+  z-index: 2;
+}
+.hero-illus { position: absolute; inset: 0; }
+.illus-lamp::before {
+  content: "";
+  position: absolute;
+  left: 50%; top: 18%;
+  width: 60%; height: 60%;
+  transform: translateX(-50%);
+  background:
+    radial-gradient(circle at 50% 30%, rgba(217,179,130,.55), rgba(217,179,130,0) 55%),
+    radial-gradient(circle at 50% 35%, rgba(217,179,130,.85) 0 18%, transparent 19%);
+  filter: blur(.4px);
+}
+.illus-lamp::after {
+  content: "";
+  position: absolute;
+  left: 50%; bottom: 12%;
+  width: 2px; height: 38%;
+  background: linear-gradient(to top, var(--accent), rgba(217,179,130,0));
+  transform: translateX(-50%);
+}
+.illus-circle::before {
+  content: "";
+  position: absolute;
+  inset: 18%;
+  border-radius: 50%;
+  border: 1px solid rgba(217,179,130,.4);
+}
+.illus-circle::after {
+  content: "";
+  position: absolute;
+  inset: 30%;
+  border-radius: 50%;
+  background: radial-gradient(circle at 35% 30%, #2a2f3a, #0e1116 70%);
+  box-shadow: inset 0 0 30px rgba(0,0,0,.6);
+}
+.illus-grid {
+  background-image:
+    linear-gradient(rgba(255,255,255,.05) 1px, transparent 1px),
+    linear-gradient(90deg, rgba(255,255,255,.05) 1px, transparent 1px);
+  background-size: 22px 22px;
+  background-position: -1px -1px;
+}
+
+/* Categories */
+.categories { padding: 32px 0 32px; }
+.cat-grid {
+  list-style: none; padding: 0; margin: 0;
+  display: grid;
+  grid-template-columns: repeat(6, minmax(0,1fr));
+  gap: 12px;
+}
+.cat-card {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 10px;
+  padding: 22px 12px;
+  border-radius: var(--radius);
+  border: 1px solid var(--line);
+  background: var(--bg-elev);
+  text-decoration: none;
+  color: var(--text);
+  font-weight: 500;
+  font-size: .92rem;
+  text-align: center;
+  transition: transform .15s, border-color .15s, background .15s;
+}
+.cat-card:hover {
+  transform: translateY(-2px);
+  border-color: var(--line-strong);
+  background: var(--bg-elev-2);
+}
+.cat-emoji { font-size: 1.6rem; line-height: 1; }
+
+/* Filter chips */
+.filter-bar {
+  display: flex;
+  gap: 8px;
+  flex-wrap: wrap;
+}
+.chip {
+  padding: 8px 14px;
+  background: transparent;
+  color: var(--text-muted);
+  border: 1px solid var(--line);
+  border-radius: 999px;
+  font-size: .85rem;
+  font-weight: 500;
+  cursor: pointer;
+  transition: color .15s, background .15s, border-color .15s;
+  font-family: inherit;
+}
+.chip:hover { color: var(--text); border-color: var(--line-strong); }
+.chip.is-active {
+  background: var(--text);
+  color: var(--bg);
+  border-color: var(--text);
+}
+
+/* Product grid */
+.product-grid {
+  list-style: none; padding: 0; margin: 0;
+  display: grid;
+  grid-template-columns: repeat(4, minmax(0,1fr));
+  gap: 22px;
+}
+.product {
+  display: flex;
+  flex-direction: column;
+  background: var(--bg-elev);
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  overflow: hidden;
+  transition: transform .15s, border-color .15s;
+}
+.product:hover { transform: translateY(-3px); border-color: var(--line-strong); }
+.product-media {
+  position: relative;
+  aspect-ratio: 4 / 5;
+  overflow: hidden;
+}
+.product-art {
+  position: absolute; inset: 0;
+}
+.product-tag {
+  position: absolute;
+  top: 12px; left: 12px;
+  font-size: .68rem;
+  letter-spacing: .14em;
+  text-transform: uppercase;
+  font-weight: 700;
+  padding: 5px 9px;
+  border-radius: 999px;
+  background: rgba(11,12,16,.7);
+  color: var(--text);
+  border: 1px solid var(--line);
+}
+.product-tag.new { color: var(--accent); border-color: rgba(217,179,130,.4); }
+.product-tag.sale { color: #ffb3b3; border-color: rgba(255,140,140,.4); }
+
+.product-fav {
+  position: absolute;
+  top: 10px; right: 10px;
+  width: 36px; height: 36px;
+  border-radius: 50%;
+  background: rgba(11,12,16,.6);
+  border: 1px solid var(--line);
+  color: var(--text-muted);
+  cursor: pointer;
+  display: grid; place-items: center;
+  transition: color .15s, background .15s;
+}
+.product-fav:hover { color: var(--text); background: rgba(11,12,16,.85); }
+.product-fav[aria-pressed="true"] { color: var(--accent); }
+
+.product-body {
+  padding: 16px 16px 18px;
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+  flex: 1;
+}
+.product-cat {
+  font-size: .72rem;
+  letter-spacing: .14em;
+  text-transform: uppercase;
+  color: var(--text-soft);
+  margin: 0;
+}
+.product-name {
+  margin: 0;
+  font-family: var(--font-display);
+  font-size: 1.05rem;
+  font-weight: 600;
+  line-height: 1.25;
+}
+.product-foot {
+  margin-top: auto;
+  padding-top: 12px;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+}
+.product-price {
+  font-weight: 600;
+  font-size: 1rem;
+}
+.product-price s {
+  color: var(--text-soft);
+  font-weight: 400;
+  margin-left: 6px;
+  font-size: .9rem;
+}
+.add-btn {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  padding: 8px 14px;
+  border-radius: 999px;
+  background: var(--surface);
+  color: var(--text);
+  border: 1px solid var(--line-strong);
+  font-size: .82rem;
+  font-weight: 600;
+  cursor: pointer;
+  font-family: inherit;
+  transition: background .15s, color .15s;
+}
+.add-btn:hover { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
+
+/* Product art variants */
+.art-1 { background:
+  radial-gradient(80% 60% at 50% 35%, rgba(217,179,130,.35), transparent 60%),
+  linear-gradient(160deg, #20242e, #11141a); }
+.art-1::after {
+  content: ""; position: absolute;
+  left: 50%; top: 30%; width: 38%; height: 38%;
+  transform: translateX(-50%);
+  border-radius: 50%;
+  background: radial-gradient(circle at 35% 30%, #d9b382, #5a431f 70%, #1a1408);
+  box-shadow: 0 30px 60px -20px rgba(0,0,0,.7);
+}
+.art-2 { background:
+  linear-gradient(170deg, #1a1f29, #0d1015);
+}
+.art-2::before, .art-2::after {
+  content: ""; position: absolute;
+  background: linear-gradient(180deg, #2a2f3a, #14171e);
+  border: 1px solid #353b48;
+  border-radius: 8px;
+}
+.art-2::before { left: 22%; bottom: 18%; width: 24%; height: 55%; }
+.art-2::after  { left: 52%; bottom: 18%; width: 28%; height: 70%; }
+
+.art-3 { background:
+  radial-gradient(70% 50% at 50% 60%, rgba(140,170,220,.18), transparent 60%),
+  linear-gradient(170deg, #181c25, #0e1116); }
+.art-3::after {
+  content: ""; position: absolute;
+  left: 25%; right: 25%; top: 30%; bottom: 25%;
+  background: linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.01));
+  border: 1px solid rgba(255,255,255,.08);
+  border-radius: 6px 6px 30px 30px;
+}
+
+.art-4 { background:
+  linear-gradient(150deg, #2b2218, #14110c);
+}
+.art-4::after {
+  content: ""; position: absolute;
+  inset: 24% 28%;
+  background:
+    repeating-linear-gradient(45deg, rgba(217,179,130,.18) 0 6px, transparent 6px 14px),
+    #1a1610;
+  border-radius: 8px;
+  border: 1px solid rgba(217,179,130,.15);
+}
+
+.art-5 { background:
+  radial-gradient(60% 60% at 50% 50%, rgba(217,179,130,.18), transparent 65%),
+  linear-gradient(170deg, #1c2029, #0d1015); }
+.art-5::after {
+  content: ""; position: absolute;
+  left: 30%; top: 22%; width: 40%; height: 56%;
+  border-radius: 50% 50% 14px 14px / 60% 60% 14px 14px;
+  background: linear-gradient(180deg, #d9b382, #6b4f25);
+  box-shadow: inset 0 -20px 30px rgba(0,0,0,.4);
+}
+
+.art-6 { background:
+  linear-gradient(170deg, #1f1a25, #0f0c14); }
+.art-6::after {
+  content: ""; position: absolute;
+  inset: 25% 30%;
+  background: radial-gradient(circle at 30% 30%, #4a3e5e, #1c1626);
+  border-radius: 50%;
+}
+
+.art-7 { background:
+  linear-gradient(170deg, #14211f, #08110f); }
+.art-7::after {
+  content: ""; position: absolute;
+  left: 30%; top: 25%; width: 40%; height: 50%;
+  background: linear-gradient(180deg, #2c5650, #103129);
+  border-radius: 14px;
+  border: 1px solid rgba(140,200,180,.2);
+}
+
+.art-8 { background:
+  radial-gradient(80% 60% at 50% 40%, rgba(255,180,160,.15), transparent 60%),
+  linear-gradient(170deg, #25181a, #14090b); }
+.art-8::after {
+  content: ""; position: absolute;
+  left: 32%; top: 25%; width: 36%; height: 50%;
+  border-radius: 50%;
+  background: radial-gradient(circle at 30% 30%, #b07a6a, #4a221d);
+}
+
+/* Deals */
+.deals { background:
+  linear-gradient(180deg, transparent, rgba(217,179,130,.04), transparent);
+}
+.countdown {
+  display: inline-flex;
+  align-items: baseline;
+  gap: 10px;
+  padding: 10px 16px;
+  border: 1px solid var(--line-strong);
+  border-radius: 999px;
+  background: var(--bg-elev);
+  font-variant-numeric: tabular-nums;
+}
+.countdown-label {
+  font-size: .75rem;
+  letter-spacing: .14em;
+  text-transform: uppercase;
+  color: var(--text-soft);
+}
+.countdown-time {
+  font-family: var(--font-display);
+  font-weight: 600;
+  font-size: 1.05rem;
+  color: var(--accent);
+}
+
+.deals-grid {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0,1fr));
+  grid-template-rows: auto auto;
+  gap: 18px;
+}
+.deal {
+  position: relative;
+  background: var(--bg-elev);
+  border: 1px solid var(--line);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  min-height: 280px;
+}
+.deal-feature {
+  grid-column: span 2;
+  grid-row: span 2;
+  flex-direction: row;
+  min-height: 360px;
